mapper.select:
SELECT provider_type AS platformType, external_store_id AS externalStoreId,
       spend_date AS spendDate, campaign_name AS campaignName,
       spend_amount AS spendAmount
FROM external_ad_spend_daily
WHERE provider_type = #{platformType}
  AND external_store_id = #{externalStoreId}
AND spend_date >= #{from}
AND spend_date <= #{to}
ORDER BY spend_date ASC, id ASC

